SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'wasserproben', 'Wasseranalysen (Füllwasser / Schwimmbereich — Tab. 7 / Tab. 8 je Probe)', 'json', NULL, false, '§7.1.1, Tab. 7; §7.1.2, Tab. 8', 'Plan 3: Zeilen je Probe (Datum, Ort, Ammonium, Eisen, P_total, Härte, Leitfähigkeit, Mangan, Nitrat, Nitrit, Orthophosphat, Säurekapazität, pH; Eisen / Mangan nur Füllwasser, Nitrit nur Schwimmbereich); je Zeile Vergleich mit TABLE7 / TABLE8 / TABLE8_P (P-Werte im Schwimmbereich nach natural_pool_type — unentscheidbar bis fll_naturteich-C-1); Anzahl → sample_count (FLLNT-04-D2), Verletzungen → sample_violations (FLLNT-04-D1); die 21 Skalare water_test_* / swimming_test_* bleiben (REQ-09 / REQ-10), Ablösung STAGED (fll_naturteich-G-4).', 'imported_unverified', 'Table 7: Approximate chemical values for the fill-up water – if applicable, after purification — Table 8: Approximate chemical values for the swimming area — If the analysis results deviate from the approximate values, the biological processes must be observed and if applicable, an advanced total water analysis must be implemented and re- spective measures taken. Temporary fluctuations (e.g. due to environmental influences) can occur.', 'register', '{"title":"Wasseranalysen","subtitle":"Tab. 7 (Füllwasser) / Tab. 8 (Schwimmbereich) — je Probe Datum, Ort und Parameter; Richtwerte je Zeile, P-Werte im Schwimmbereich nach Typ (I–III: ≤ 0.03 · IV / V: ≤ 0.01 mg/l)","add_label":"+ Probe","placement":"section","columns":[{"key":"date","label":"Datum","type":"date","required":true},{"key":"location","label":"Ort","type":"enum","required":true,"options":["fill","swimming"],"option_labels":{"fill":"Füllwasser (Tab. 7)","swimming":"Schwimmbereich (Tab. 8)"},"discriminator":true},{"key":"ammonium","label":"Ammonium","type":"number","unit":"mg/l","required":true,"min":0,"aria_label":"Ammonium der Probe"},{"key":"iron","label":"Eisen (Iron)","type":"number","unit":"mg/l","required":true,"min":0,"aria_label":"Eisen (Iron) der Probe","visible_when":"location == ''fill''"},{"key":"p_total","label":"Gesamtphosphor (Ptotal)","type":"number","unit":"mg/l","required":true,"min":0,"aria_label":"Gesamtphosphor (Ptotal) der Probe"},{"key":"hardness","label":"Härte (total alkaline earth)","type":"number","unit":"mmol/l","required":true,"min":0,"aria_label":"Härte (total alkaline earth) der Probe"},{"key":"conductivity","label":"Leitfähigkeit bei 20 °C","type":"number","unit":"μS/cm","required":true,"min":0,"aria_label":"Leitfähigkeit bei 20 °C der Probe"},{"key":"manganese","label":"Mangan (Manganese)","type":"number","unit":"mg/l","required":true,"min":0,"aria_label":"Mangan (Manganese) der Probe","visible_when":"location == ''fill''"},{"key":"nitrate","label":"Nitrat","type":"number","unit":"mg/l","required":true,"min":0,"aria_label":"Nitrat der Probe"},{"key":"nitrite","label":"Nitrit","type":"number","unit":"mg/l","required":true,"min":0,"aria_label":"Nitrit der Probe","visible_when":"location == ''swimming''"},{"key":"orthophosphate","label":"Orthophosphat (als P)","type":"number","unit":"mg/l","required":true,"min":0,"aria_label":"Orthophosphat (als P) der Probe"},{"key":"acid_capacity","label":"Säurekapazität KS 4.3","type":"number","unit":"mmol/l","required":true,"min":0,"aria_label":"Säurekapazität KS 4.3 der Probe"},{"key":"ph","label":"pH","type":"number","unit":"-","required":true,"min":0,"max":14,"aria_label":"pH-Wert der Probe"},{"key":"ammonium_ok","label":"Ammonium ok","type":"derived","expr":"if(ammonium <= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''ammonium_max''), lookup(''TABLE8'', ''all'', ''ammonium_max'')), 1, 0)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"iron_ok","label":"Eisen (Iron) ok","type":"derived","expr":"if(location == ''fill'', if(iron <= lookup(''TABLE7'', ''all'', ''iron_max''), 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"p_total_ok","label":"Gesamtphosphor (Ptotal) ok","type":"derived","expr":"if(p_total <= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''p_total_max''), lookup(''TABLE8_P'', natural_pool_type, ''p_total_max'')), 1, 0)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"hardness_ok","label":"Härte (total alkaline earth) ok","type":"derived","expr":"if(hardness >= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''hardness_min''), lookup(''TABLE8'', ''all'', ''hardness_min'')), 1, 0)","display":"badge","value_labels":{"0":"unterschritten","1":"ok"}},{"key":"conductivity_ok","label":"Leitfähigkeit bei 20 °C ok","type":"derived","expr":"if(conductivity <= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''conductivity_max''), lookup(''TABLE8'', ''all'', ''conductivity_max'')), 1, 0)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"manganese_ok","label":"Mangan (Manganese) ok","type":"derived","expr":"if(location == ''fill'', if(manganese <= lookup(''TABLE7'', ''all'', ''manganese_max''), 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"nitrate_ok","label":"Nitrat ok","type":"derived","expr":"if(nitrate <= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''nitrate_max''), lookup(''TABLE8'', ''all'', ''nitrate_max'')), 1, 0)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"nitrite_ok","label":"Nitrit ok","type":"derived","expr":"if(location == ''swimming'', if(nitrite <= lookup(''TABLE8'', ''all'', ''nitrite_max''), 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"orthophosphate_ok","label":"Orthophosphat (als P) ok","type":"derived","expr":"if(orthophosphate <= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''orthophosphate_max''), lookup(''TABLE8_P'', natural_pool_type, ''orthophosphate_max'')), 1, 0)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"acid_capacity_ok","label":"Säurekapazität KS 4.3 ok","type":"derived","expr":"if(acid_capacity >= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''acid_capacity_min''), lookup(''TABLE8'', ''all'', ''acid_capacity_min'')), 1, 0)","display":"badge","value_labels":{"0":"unterschritten","1":"ok"}},{"key":"ph_ok","label":"pH ok","type":"derived","expr":"if(ph >= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''ph_min''), lookup(''TABLE8'', ''all'', ''ph_min'')) AND ph <= if(location == ''fill'', lookup(''TABLE7'', ''all'', ''ph_max''), lookup(''TABLE8'', ''all'', ''ph_max'')), 1, 0)","display":"badge","value_labels":{"0":"außerhalb","1":"ok"}},{"key":"sample_ok","label":"Probe","type":"derived","expr":"if(ammonium_ok == 1 AND iron_ok == 1 AND p_total_ok == 1 AND hardness_ok == 1 AND conductivity_ok == 1 AND manganese_ok == 1 AND nitrate_ok == 1 AND nitrite_ok == 1 AND orthophosphate_ok == 1 AND acid_capacity_ok == 1 AND ph_ok == 1, 1, 0)","display":"badge","value_labels":{"0":"Richtwert abweichend","1":"alle Richtwerte eingehalten"}}],"footer":["sample_count","sample_violations"],"note":"If the analysis results deviate from the approximate values, the biological processes must be observed and if applicable, an advanced total water analysis must be implemented and re- spective measures taken. Temporary fluctuations (e.g. due to environmental influences) can occur."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
