SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'substrate_role', 'Substratrolle nach Tab. 9 (Filtersubstrat Typ III / Filtersubstrat Typ IV / Pflanzsubstrat)', 'enum', NULL, false, '§7.2.3, Tab. 9', 'Plan 3: Treiber der TABLE9-Spalte für die sechs Anforderungswerte (*_tab9); Tab. 9 druckt die drei Spalten als eigene Rollen — der Naturteich-Typ (FLLNT-03) ist auf FLLNT-05 nicht vererbt und legt die Rolle nicht allein fest (Pflanzsubstrat in jedem Typ). Die Hälfte filter_iii / filter_iv wird NICHT gegen natural_pool_type plausibilisiert (nicht in Reichweite); eine spätere Ableitung braucht zuerst den Consumer-Edit FLLNT-03 → FLLNT-05 (Muster fll_naturteich-C-1).', 'imported_unverified', 'Table 9: Requirements pertaining to filter substrates and plant substrates — Recommended maxi- mum grain size 16 mm 32 mm 8 mm — The percentage of oversized grain must not exceed 15% by weight. Filter substrates that are used in controlled quick flow through filter bodies (natural pool type IV) should indicate a silt and clay percentage (< 0.063 mm) of ≤ 0.5% by weight; a threshold value of ≤ 2% by weight applies here for all other filter substrates. The level of elutable phosphorus should not exceed 5 mg P/kg.', 'select_one', NULL, NULL, NULL, '[{"value":"filter_iii","label_de":"Filter substrate natural pool type III","order_index":0},{"value":"filter_iv","label_de":"Filter substrate natural pool type IV","order_index":1},{"value":"plant","label_de":"Plant substrate","order_index":2}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'substrate_role') AND w.code = 'FLLNT-05' AND s.code = 'FLL-Naturteich';
