SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'zonen', 'Teilflächen / Zonen (Schwimm-, Regenerations-, Ergänzungsflächen → Σ, Anteil, Unterwasserfläche)', 'json', NULL, false, '§3; §5, Tab. 1–3; §9.2; App. 5', 'Plan 3: Zeilen je Zone (Art, Fläche, Tiefe, Boden-/Wandfläche unter Wasser, Regenerationstechnik mit den prod-Token von regeneration_technique); Σ → total_pool_area_calc (FLLNT-06-D1), Regenerationsanteil an der Wasserfläche (Schwimm- + Regenerationsbereich, Tab. 2–6 "of the total water area") → regeneration_share_calc (FLLNT-06-D2), Σ Boden + Wand → pool_underwater_surface_calc (FLLNT-06-D3), submerser Anteil am Regenerationsbereich → submerged_hydrobot_share_calc (FLLNT-06-D4); Ablösung der Skalare swimming_area_m2 / regeneration_area_m2 / supplementary_area_m2 / total_pool_area_m2 und von EQ-PUWS STAGED (fll_naturteich-R-1 / -R-2); Ergänzungsflächen zählen nicht zur Wasserfläche (fll_naturteich-J-4).', 'imported_unverified', 'Regeneration area The area used for biological, physical and physical/chemical purification of the water which is not accessible to swimmers. It consists of the plant zone and/or filtration zone as well as the water therein. — Supplementary area Areas which do not belong directly to the natural swimming pool but are added for their use, e. g. paths and access routes to the pool, rest areas and areas for lying down, playing areas for children. — Natural pools must be separated into a swimming area and a regeneration area. The area used by swimmers must be kept separate from the regeneration area by at least an — Biological characteristics Regeneration area in % of the total water area — Dimension of the regenera- tion area compared to the total area > 50% > 50% > 30%', 'register', '{"title":"Teilflächen (Zonen)","subtitle":"§3 / §5 Tab. 1 / §9.2 — je Zone Art, Fläche, Tiefe; Regenerationszonen mit Technik; Boden- und Wandflächen unter Wasser für die 50×-Regel (App. 5)","add_label":"+ Zone","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text","required":true},{"key":"zone","label":"Zone","type":"enum","required":true,"options":["swimming","regeneration","supplementary"],"option_labels":{"swimming":"Schwimmbereich (swimming area)","regeneration":"Regenerationsbereich (regeneration area — Pflanz-/Filterzone, nicht für Schwimmer zugänglich)","supplementary":"Ergänzungsfläche (supplementary area — Wege, Liegeflächen; gehört nicht zur Wasserfläche)"},"discriminator":true},{"key":"area_m2","label":"Fläche","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Wasserfläche der Zone"},{"key":"depth_m","label":"Wassertiefe","type":"number","unit":"m","min":0,"aria_label":"Wassertiefe der Zone"},{"key":"ground_area_m2","label":"Bodenfläche unter Wasser","type":"number","unit":"m²","min":0,"aria_label":"Bodenfläche unter Wasser (App. 5)"},{"key":"wall_area_m2","label":"Wandfläche unter Wasser","type":"number","unit":"m²","min":0,"aria_label":"Wandfläche unter Wasser (App. 5)"},{"key":"technique","label":"Regenerationstechnik","type":"enum","required":true,"options":["hydrobotanical_submergent","hydrobotanical_emersed","substrate_filter_slow","substrate_filter_quick","technical_unit","physical_chemical"],"option_labels":{"hydrobotanical_submergent":"hydrobotanisch, submergent","hydrobotanical_emersed":"hydrobotanisch, emers","substrate_filter_slow":"Substratfilter, langsam durchströmt","substrate_filter_quick":"Substratfilter, schnell durchströmt","technical_unit":"technische Einheit","physical_chemical":"physikalisch/chemisch (nur ergänzend, §10.2.5)"},"visible_when":"zone == ''regeneration''"},{"key":"underwater_m2","label":"Unterwasserfläche","type":"derived","expr":"if(ground_area_m2 IS NULL, 0, ground_area_m2) + if(wall_area_m2 IS NULL, 0, wall_area_m2)","unit":"m²"}],"footer":["total_pool_area_calc","regeneration_share_calc","pool_underwater_surface_calc","submerged_hydrobot_share_calc"],"note":"Biological characteristics Regeneration area in % of the total water area"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'zonen') AND w.code = 'FLLNT-06' AND s.code = 'FLL-Naturteich';
