SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'regeneration_share_calc', 'Regenerationsanteil an der Gesamtwasserfläche aus den Zonen (Σ Regeneration / Σ (Schwimm + Regeneration) · 100)', 'number', '%', false, '§5, Tab. 1–3 ("Regeneration area in % of the total water area")', 'Plan 3: Ausgabe der Gleichung FLLNT-06-D2; Vergleich mit regeneration_share_min_pct (FLLNT-03) und REQ-07-Umbindung STAGED (fll_naturteich-G-1); Ergänzungsflächen nicht im Nenner (fll_naturteich-J-4).', 'imported_unverified', 'Biological characteristics Regeneration area in % of the total water area — Dimension of the regenera- tion area compared to the total area > 50% > 50% > 30%', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'regeneration_share_calc') AND w.code = 'FLLNT-06' AND s.code = 'FLL-Naturteich';
