SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'pool_underwater_surface_calc', 'Σ Unterwasserfläche aus den Zonen (Boden + Wände unter Wasser, App. 5)', 'number', 'm²', false, '§10.2.3; App. 5', 'Plan 3: Ausgabe der Gleichung FLLNT-06-D3 (sum_rows über zonen.underwater_m2); Ablösung von EQ-PUWS (pool_underwater_surface = pool_ground_area_m2 + pool_submerged_wall_area_m2) STAGED (fll_naturteich-R-2).', 'imported_unverified', 'The outer grain surfaces of the filter material in the filter body that can be colonized should, as experience shows, amount to at least 50-times the surfaces of the pool that are exposed to light and inundated (refer to Appendix 5). Among others these surfaces include: • surface of the bottom of the pool and pool walls; • “decorative surfaces” (gravel areas with no flow, rocks for design purposes, etc.) — Filter cross-section F: 15 m2 Filter height: 0.7 m Surface grain size 8-16 mm (according to Table 1): 600 m2 /m3 Surface of the filter body = 600 m2 /m3 x 15 m2 x 0.7 m = 6300 m2', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'pool_underwater_surface_calc') AND w.code = 'FLLNT-06' AND s.code = 'FLL-Naturteich';
