SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'hydrobot_grain_max_tab10', 'Korngröße Pflanzsubstrat, maximal — Tab. 10 (≤ 8 mm)', 'number', 'mm', false, '§10.2.1, Tab. 10', 'Plan 3: Grenzwert aus TABLE10 zur gewählten Regenerationstechnik (submergent / Emersed); die Eingaben hydrobot_water_column / hydrobot_substrate_thickness / hydrobot_grain_size_max / hydrobot_feed_rate bleiben — REQ-19 vergleicht heute mit den Literalen (fll_naturteich-G-3).', 'imported_unverified', 'Table 10: Structural requirements for hydrobotanical systems — 5 Grain size range1 ) Location of the plant ≤ 8 mm Filters — —', 'lookup_fill', '{"source_label":"Tab. 10"}'::jsonb, '{"table_code":"TABLE10","role":"limit","keys":[{"column":"hydrobot_type","from_symbol":"hydrobot_type"}],"value":"grain_max_mm"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'hydrobot_grain_max_tab10') AND w.code = 'FLLNT-09' AND s.code = 'FLL-Naturteich';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'hydrobot_feed_qmax_tab10', 'Beschickung Qmax — Tab. 10 (5 m3/(m2 x day))', 'number', 'm³/(m²·d)', false, '§10.2.1, Tab. 10', 'Plan 3: Grenzwert aus TABLE10 zur gewählten Regenerationstechnik (submergent / Emersed); die Eingaben hydrobot_water_column / hydrobot_substrate_thickness / hydrobot_grain_size_max / hydrobot_feed_rate bleiben — REQ-19 vergleicht heute mit den Literalen (fll_naturteich-G-3).', 'imported_unverified', 'Table 10: Structural requirements for hydrobotanical systems — 12 Feed rate Qmax 5 m3/(m2 x day) 5 m3/(m2 x day)', 'lookup_fill', '{"source_label":"Tab. 10"}'::jsonb, '{"table_code":"TABLE10","role":"limit","keys":[{"column":"hydrobot_type","from_symbol":"hydrobot_type"}],"value":"feed_rate_qmax"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'hydrobot_feed_qmax_tab10') AND w.code = 'FLLNT-09' AND s.code = 'FLL-Naturteich';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'filtereinheiten', 'Filter- / Hydrobotanik-Einheiten (Tab. 10 / 11 / 12 je Einheit, Tab. 15 Kornklasse → besiedelbare Oberfläche)', 'json', NULL, false, '§10.2.1–10.2.4, Tab. 10–12; App. 5, Tab. 15', 'Plan 3: Zeilen je Einheit (Art als Diskriminator: hydrobotanisch mit prod hydrobot_type-Token / Substratfilter mit prod filter_flow_type- und filter_flow_direction-Token / technische Einheit; Fläche, wirksame Schicht, Kornklasse nach Tab. 15 mit Oberfläche (anhaltswert — Produktwert mit Begründung), Beschickung); je Zeile Schichtminimum, besiedelbare Oberfläche (App. 5 Beispiel 1: 600 · 15 · 0.7 = 6300 m²) und Beschickungsgrenze aus TABLE10 / TABLE11 / TABLE12; Σ → filter_colonized_surface_total (FLLNT-10-D1), Verletzungen → filter_feed_violations (FLLNT-10-D2); Ablösung von EQ-02 / EQ-01 / EQ-03 und der Skalare grain_specific_surface / F_filter / h_filter STAGED (fll_naturteich-R-3 / -G-6).', 'imported_unverified', 'Table 10: Structural requirements for hydrobotanical systems — Table 11: Structural requirements for substrate filters with a controlled slow flow — Table 12: Structural requirements for substrate filters with a controlled quick flow — The outer grain surfaces of the filter material in the filter body that can be colonized should, as experience shows, amount to at least 50-times the surfaces of the pool that are exposed to light and inundated (refer to Appendix 5). Among others these surfaces include: • surface of the bottom of the pool and pool walls; • “decorative surfaces” (gravel areas with no flow, rocks for design purposes, etc.) — Filter cross-section F: 15 m2 Filter height: 0.7 m Surface grain size 8-16 mm (according to Table 1): 600 m2 /m3 Surface of the filter body = 600 m2 /m3 x 15 m2 x 0.7 m = 6300 m2 — Table 15: Grain sizes – surfaces — The values were determined using dolomite gravel — The manufacturer’s instructions must be observed (e.g. feed rate, cleaning, operation).', 'register', '{"title":"Filter- / Hydrobotanik-Einheiten","subtitle":"Tab. 10 / 11 / 12 — je Einheit Technik, Fließrichtung, Fläche, Schicht und Kornklasse (Tab. 15); besiedelbare Oberfläche je Zeile (App. 5), Beschickung gegen Qmax / Qmin","add_label":"+ Einheit","placement":"section","columns":[{"key":"label","label":"Einheit","type":"text","required":true},{"key":"unit_kind","label":"Art","type":"enum","required":true,"options":["hydrobotanical","substrate_filter","technical"],"option_labels":{"hydrobotanical":"Hydrobotanisches System (§10.2.1, Tab. 10)","substrate_filter":"Substratfilter (§10.2.2 / 10.2.3, Tab. 11 / 12)","technical":"Technische Einheit (§10.2.4, Herstellerangaben)"},"discriminator":true},{"key":"hydrobot_type","label":"Hydrobotanik-Typ (Tab. 10)","type":"enum","required":true,"options":["submergent","emersed"],"option_labels":{"submergent":"submergent","emersed":"Emersed"},"visible_when":"unit_kind == ''hydrobotanical''"},{"key":"flow_type","label":"Durchströmung","type":"enum","required":true,"options":["slow","quick"],"option_labels":{"slow":"controlled slow flow (Tab. 11)","quick":"controlled quick flow (Tab. 12)"},"visible_when":"unit_kind == ''substrate_filter''"},{"key":"flow_direction","label":"Fließrichtung","type":"enum","required":true,"options":["vertical_continuous_overflow","vertical_no_overflow","horizontal"],"option_labels":{"vertical_continuous_overflow":"vertikal durchströmt, kontinuierlicher ganzflächiger Überlauf","vertical_no_overflow":"vertikal durchströmt, ohne Überlauf","horizontal":"horizontal durchströmt (Einzelnachweis, keine weiteren Angaben)"},"visible_when":"unit_kind == ''substrate_filter''"},{"key":"area_m2","label":"F_filter","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Filterfläche / Querschnitt der Einheit"},{"key":"layer_cm","label":"wirksame Schicht","type":"number","unit":"cm","required":true,"min":0,"visible_when":"unit_kind != ''technical''","aria_label":"Dicke der filterwirksamen Schicht bzw. Substratschicht"},{"key":"layer_min","label":"Schicht min (Tab.)","type":"derived","expr":"if(unit_kind == ''hydrobotanical'', lookup(''TABLE10'', hydrobot_type, ''substrate_min_cm''), if(unit_kind == ''substrate_filter'', if(flow_type == ''slow'', lookup(''TABLE11'', flow_direction, ''layer_min_cm''), lookup(''TABLE12'', flow_direction, ''layer_min_cm'')), 0))","unit":"cm"},{"key":"layer_ok","label":"Schicht","type":"derived","expr":"if(unit_kind == ''technical'', 1, if(unit_kind == ''substrate_filter'' AND flow_direction == ''horizontal'', 1, if(unit_kind == ''hydrobotanical'', if(layer_cm >= layer_min AND layer_cm <= lookup(''TABLE10'', hydrobot_type, ''substrate_max_cm''), 1, 0), if(layer_cm >= layer_min, 1, 0))))","display":"badge","value_labels":{"0":"Schichtdicke außerhalb Tab. 10 / 11 / 12","1":"Schichtdicke nach Tab. 10 / 11 / 12"}},{"key":"grain_class","label":"Kornklasse (Tab. 15)","type":"lookup_key","required":true,"lookup":{"table_code":"TABLE15"},"visible_when":"unit_kind == ''substrate_filter''"},{"key":"surface_m2_m3","label":"Oberfläche","type":"lookup_value","unit":"m²/m³","lookup":{"table_code":"TABLE15","key_column":"grain_class","value":"surface_m2_m3"},"visible_when":"unit_kind == ''substrate_filter''"},{"key":"surface_override","label":"Produktwert","type":"boolean","visible_when":"unit_kind == ''substrate_filter''"},{"key":"colonized_manual_m2","label":"besiedelbare Oberfläche (Hersteller)","type":"number","unit":"m²","min":0,"visible_when":"unit_kind == ''technical''","aria_label":"besiedelbare Oberfläche nach Herstellerangabe"},{"key":"colonized_m2","label":"besiedelbare Oberfläche","type":"derived","expr":"if(unit_kind == ''substrate_filter'', surface_m2_m3 * area_m2 * layer_cm / 100, if(unit_kind == ''technical'', if(colonized_manual_m2 IS NULL, 0, colonized_manual_m2), 0))","unit":"m²"},{"key":"feed_rate","label":"Beschickung","type":"number","unit":"m³/(m²·d)","min":0,"aria_label":"Beschickung der Einheit"},{"key":"feed_limit","label":"Beschickung Grenze","type":"derived","expr":"if(unit_kind == ''hydrobotanical'', lookup(''TABLE10'', hydrobot_type, ''feed_rate_qmax''), if(unit_kind == ''substrate_filter'', if(flow_type == ''slow'', lookup(''TABLE11'', flow_direction, ''feed_rate_qmax''), lookup(''TABLE12'', flow_direction, ''feed_rate_qmin'')), 0))","unit":"m³/(m²·d)"},{"key":"feed_ok","label":"Beschickung","type":"derived","expr":"if(feed_rate IS NULL, 1, if(unit_kind == ''technical'', 1, if(unit_kind == ''substrate_filter'' AND flow_direction == ''horizontal'', 1, if(unit_kind == ''substrate_filter'' AND flow_type == ''quick'', if(feed_rate >= feed_limit, 1, 0), if(feed_rate <= feed_limit, 1, 0)))))","display":"badge","value_labels":{"0":"Beschickung außerhalb Qmax / Qmin","1":"Beschickung nach Tab. 10 / 11 / 12"}}],"override":{"flag_key":"surface_override","applies_to":["surface_m2_m3"],"policy":"anhaltswert"},"footer":["filter_colonized_surface_total","filter_feed_violations"],"note":"Size of the grain surface depends on its composition of grain sizes"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filtereinheiten') AND w.code = 'FLLNT-10' AND s.code = 'FLL-Naturteich';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'filter_colonized_surface_total', 'Σ besiedelbare Oberfläche über die Filter-Einheiten (App. 5)', 'number', 'm²', false, '§10.2.3; App. 5', 'Plan 3: Ausgabe der Gleichung FLLNT-10-D1 (sum_rows über filtereinheiten.colonized_m2); Ablösung von EQ-02 (filter_colonized_surface_actual = grain_specific_surface · F_filter · h_filter) und die 50×-Regel EQ-01 darauf STAGED (fll_naturteich-R-3 / -G-6).', 'imported_unverified', 'The outer grain surfaces of the filter material in the filter body that can be colonized should, as experience shows, amount to at least 50-times the surfaces of the pool that are exposed to light and inundated (refer to Appendix 5). Among others these surfaces include: • surface of the bottom of the pool and pool walls; • “decorative surfaces” (gravel areas with no flow, rocks for design purposes, etc.) — Specifications: The outer grain surfaces of the filter material in the filter body that can be colo- nized should, as experience shows, amount to at least 50-times the surfaces of the pool that are exposed to light and submerged. — Filter cross-section F: 15 m2 Filter height: 0.7 m Surface grain size 8-16 mm (according to Table 1): 600 m2 /m3 Surface of the filter body = 600 m2 /m3 x 15 m2 x 0.7 m = 6300 m2', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filter_colonized_surface_total') AND w.code = 'FLLNT-10' AND s.code = 'FLL-Naturteich';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'filter_feed_violations', 'Anzahl Einheiten mit Beschickung außerhalb Qmax (Tab. 10 / 11) bzw. unter Qmin (Tab. 12)', 'number', NULL, false, '§10.2.1–10.2.3, Tab. 10–12', 'Plan 3: Ausgabe der Gleichung FLLNT-10-D2 (count_rows über filtereinheiten mit feed_ok == 0; horizontale Filter, technische Einheiten und Zeilen ohne Beschickung zählen nicht); Gate == 0 STAGED (fll_naturteich-G-6).', 'imported_unverified', '12 Feed rate Qmax 5 m3/(m2 x day) 5 m3/(m2 x day) — reduce the required feed rate (cf. Table 11). Furthermore, they cannot interfere with the mainte- nance of the filter surface. Otherwise plants should not be planted. — According to experience, substrate filters with a controlled quick flow must be operated with a feed rate of Qmin ≥ 15 m3/(m2 x day). Smaller feed rates are permissible if the functionality of pool is ensured. Please refer to Table 12 for information on the requirements.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filter_feed_violations') AND w.code = 'FLLNT-10' AND s.code = 'FLL-Naturteich';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'filter_flow_direction != ''horizontal''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'filter_water_column' AND w.code = 'FLLNT-10' AND s.code = 'FLL-Naturteich' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'filter_flow_direction != ''horizontal''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'filter_kf' AND w.code = 'FLLNT-10' AND s.code = 'FLL-Naturteich' AND f.active AND f.visible_when IS NULL;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'ueberlaufeinrichtungen', 'Überlauf- / Ablaufeinrichtungen (Art, Kantenlänge, Toleranz → Σ Kantenlänge)', 'json', NULL, false, '§10.3.1', 'Plan 3: Zeilen je Einrichtung (starr / flexibel, Kantenlänge, horizontale Abweichung mit der gedruckten Toleranz ±2 mm bzw. ±1 mm bis 1 m); Σ → overflow_edge_length_total (FLLNT-11-D1), Toleranzverletzungen → overflow_tolerance_violations (FLLNT-11-D2); der Richtwert 1 % der Schwimmbereichsfläche bleibt EQ-04 — dessen Ausgabe ist heute zugleich das Eingabefeld overflow_edge_length (fll_naturteich-R-4).', 'imported_unverified', '• rigid overflow weir, e.g. gully; • flexible overflow weir, e.g. skimmer. — The number, type and arrangement of the water discharge/extraction devices should be cho- sen according to the volumetric recirculation current, the local conditions and the planned type of natural pool. As a guide for the required length of overflow edge, the following value can be used for flexible and rigid overflow weirs depending on the shape and type of the natural pool: 1% of the surface area of the swimming area in metres. Example: Swimming area 30 m2, 1% of 30 = 0.3 i. e. length of the overflow edge 0.3 m. — to enable amphibians to exit. Overflow weirs are to be installed in a manner that the overflow edge does not deviate horizontally by more than +/- 2 mm or for overflow edges up to 1 m, by more than +/- 1 mm.', 'register', '{"title":"Überlauf- / Ablaufeinrichtungen","subtitle":"§10.3.1 — je Einrichtung Art (starr / flexibel), Überlaufkantenlänge, horizontale Abweichung (±2 mm; bis 1 m Kantenlänge ±1 mm); Richtwert Σ Kantenlänge = 1 % der Schwimmbereichsfläche","add_label":"+ Einrichtung","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text","required":true},{"key":"type","label":"Art","type":"enum","required":true,"options":["rigid","flexible"],"option_labels":{"rigid":"rigid overflow weir, e.g. gully","flexible":"flexible overflow weir, e.g. skimmer"}},{"key":"edge_length_m","label":"Überlaufkante","type":"number","unit":"m","required":true,"min":0,"aria_label":"Länge der Überlaufkante"},{"key":"tolerance_mm","label":"horizontale Abweichung","type":"number","unit":"mm","min":0,"aria_label":"gemessene horizontale Abweichung der Überlaufkante"},{"key":"tol_limit","label":"zulässig","type":"derived","expr":"if(edge_length_m <= 1, 1, 2)","unit":"mm"},{"key":"tol_ok","label":"Toleranz","type":"derived","expr":"if(tolerance_mm IS NULL, 1, if(tolerance_mm <= tol_limit, 1, 0))","display":"badge","value_labels":{"0":"Abweichung über ±2 / ±1 mm","1":"innerhalb ±2 / ±1 mm"}}],"footer":["overflow_edge_length_total","overflow_tolerance_violations"],"note":"The number, type and arrangement of the water discharge/extraction devices should be cho- sen according to the volumetric recirculation current, the local conditions and the planned type of natural pool. As a guide for the required length of overflow edge, the following value can be used for flexible and rigid overflow weirs depending on the shape and type of the natural pool: 1% of the surface area of the swimming area in metres. Example: Swimming area 30 m2, 1% of 30 = 0.3 i. e. length of the overflow edge 0.3 m."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ueberlaufeinrichtungen') AND w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'overflow_edge_length_total', 'Σ Überlaufkantenlänge über die Einrichtungen', 'number', 'm', false, '§10.3.1', 'Plan 3: Ausgabe der Gleichung FLLNT-11-D1 (sum_rows über ueberlaufeinrichtungen.edge_length_m); Vergleich mit dem Richtwert 0.01 · Schwimmbereichsfläche (EQ-04) STAGED (fll_naturteich-R-4).', 'imported_unverified', 'The number, type and arrangement of the water discharge/extraction devices should be cho- sen according to the volumetric recirculation current, the local conditions and the planned type of natural pool. As a guide for the required length of overflow edge, the following value can be used for flexible and rigid overflow weirs depending on the shape and type of the natural pool: 1% of the surface area of the swimming area in metres. Example: Swimming area 30 m2, 1% of 30 = 0.3 i. e. length of the overflow edge 0.3 m.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'overflow_edge_length_total') AND w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'overflow_tolerance_violations', 'Anzahl Überlaufkanten mit horizontaler Abweichung über ±2 mm (bis 1 m: ±1 mm)', 'number', NULL, false, '§10.3.1', 'Plan 3: Ausgabe der Gleichung FLLNT-11-D2 (count_rows über ueberlaufeinrichtungen mit tol_ok == 0); der Skalar overflow_horizontal_tolerance_mm bleibt (VR-Text), Gate STAGED (fll_naturteich-G-7).', 'imported_unverified', 'to enable amphibians to exit. Overflow weirs are to be installed in a manner that the overflow edge does not deviate horizontally by more than +/- 2 mm or for overflow edges up to 1 m, by more than +/- 1 mm.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'overflow_tolerance_violations') AND w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich';
UPDATE fields f SET widget = 'register', ui_config = '{"title":"Pflanzenliste","subtitle":"§10.4.1 / §10.4.3 — je Pflanzenart Gruppe (Richtwert Pflanzen je m², Topfware P 0.5), Pflanzfläche und gewählte Dichte → Stückzahl","add_label":"+ Pflanzenart","placement":"section","columns":[{"key":"art","label":"Pflanzenart","type":"text","required":true},{"key":"zone","label":"Zone / Beckentyp","type":"text"},{"key":"plant_group","label":"Pflanzengruppe (§10.4.3)","type":"lookup_key","required":true,"lookup":{"table_code":"S10_4_3"}},{"key":"area_m2","label":"Pflanzfläche","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Pflanzfläche der Art"},{"key":"density_min","label":"Dichte min (§10.4.3)","type":"lookup_value","unit":"1/m²","lookup":{"table_code":"S10_4_3","key_column":"plant_group","value":"density_min"}},{"key":"density_max","label":"Dichte max (§10.4.3)","type":"lookup_value","unit":"1/m²","lookup":{"table_code":"S10_4_3","key_column":"plant_group","value":"density_max"}},{"key":"density","label":"gewählte Dichte","type":"number","unit":"1/m²","required":true,"min":0,"aria_label":"gewählte Pflanzdichte je m²"},{"key":"in_range","label":"Richtwert","type":"derived","expr":"if(plant_group == ''lilies'', 1, if(density >= density_min AND density <= density_max, 1, 0))","display":"badge","value_labels":{"0":"außerhalb des Richtwerts §10.4.3","1":"im Richtwertbereich §10.4.3"}},{"key":"count","label":"Stück","type":"derived","expr":"area_m2 * density","unit":"Stk"},{"key":"anzahl","label":"Bemerkung (Plan-1-Spalte „Anzahl / Bemerkung“)","type":"text"}],"footer":["plant_count_total"],"note":"The aforementioned number of plants applies to pot plants P 0.5 (500 cm3)."}'::jsonb, lookup = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'plant_species_list' AND w.code = 'FLLNT-12' AND s.code = 'FLL-Naturteich' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'plant_count_total', 'Σ Pflanzen (Pflanzfläche · gewählte Dichte) über die Pflanzenliste', 'number', 'Stk', false, '§10.4.3', 'Plan 3: Ausgabe der Gleichung FLLNT-12-D1 (sum_rows über plant_species_list.area_m2 · density); die drei Dichte-Skalare plant_density_* bleiben (fll_naturteich-X-2).', 'imported_unverified', 'For plant density, the following number of plants applies as an approximate value per m2 of planting surface area: — The aforementioned number of plants applies to pot plants P 0.5 (500 cm3).', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'plant_count_total') AND w.code = 'FLLNT-12' AND s.code = 'FLL-Naturteich';
COMMIT;
